/** The full link, for a site origin like "https://dogpolicies.com/". */
export const tripUrl = (origin, trip) =>
  `${origin.replace(/\/?$/, "/")}${TRIP_PATH.slice(1)}#${encodeTrip(trip)}`;

const slotIds = (s, days) => {
  if (s == null) return Array(days).fill(null);
  if (typeof s !== "string") return undefined;
  const ids = s.split(",");
  if (ids.length > MAX_DAYS || ids.some((x) => x && !ID.test(x)))
    return undefined;
  return Array.from({ length: days }, (_, i) => ids[i] || null);
};

